const P = {"tool": "Software Invariant Analyzer"};

function demoMain(P){
  var seen={}, stack=[['N','N']], bad=false, count=0;
  var st=['N','T','C'];
  while(stack.length){
    var s=stack.pop(), k=s[0]+s[1];
    if(seen[k]) continue; seen[k]=1; count++;
    if(s[0]==='C'&&s[1]==='C') bad=true;
    for(var i=0;i<2;i++){ var t=[s[0],s[1]]; t[i]=st[(st.indexOf(s[i])+1)%3]; stack.push(t); }
  }
  return 'Model check ('+P.tool+'): '+count+' reachable states explored, mutual-exclusion invariant '+(bad?'VIOLATED':'HOLDS')+', no deadlock states found.';
}
console.log(demoMain(P));

